#pragma once

// A model provider as data: which API family it speaks, where, how it is
// authenticated, which model it is given by default, what it is called in
// the errors shown to the person, and any fixed headers it wants. The turn
// loop (ProviderAgent) and the codecs read it; the table below is the only
// place a provider's name decides anything.

#include "AgentTransport.hpp"
#include "slic3r/GUI/JusPrin/Updates/Version.hpp"

#include <optional>
#include <stdexcept>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

// The wire format a provider speaks; one codec per family.
enum class ProviderFamily { Responses, Anthropic };

// How the API key travels: `Authorization: Bearer <key>`, or `x-api-key: <key>`.
enum class AuthStyle { Bearer, ApiKeyHeader };

struct ProviderProfile
{
    std::string    id;
    ProviderFamily family{ProviderFamily::Responses};
    std::string    endpoint;
    AuthStyle      auth{AuthStyle::Bearer};
    // The provider's default; a configured model replaces it in the copy the
    // agent is built with.
    std::string    model;
    // In the error text, as in "The OpenAI API key was rejected".
    std::string    display_name;
    // Sent on every request, after the credential.
    std::vector<AgentHttpHeader> headers;
    // The most output tokens one response may use, for a family that
    // requires the number (Anthropic); 0 where none is sent.
    unsigned       max_tokens{0};
    // How hard the model thinks before a reply, chosen per chat: one of the
    // levels the provider's model list offers for this model ("low",
    // "medium", "high", ...). Empty sends nothing, so the model's own default
    // applies. Title requests never carry it.
    std::string    effort;
    // The credential is a JusPrin account's sign-in rather than an API key,
    // and the endpoint is JusPrin's gateway. Every request names its turn
    // (X-JusPrin-Turn) and says whether it is a title (X-JusPrin-Request),
    // because the gateway charges the account once per turn and never for a
    // title; a refusal means the sign-in has ended, and 402 means the
    // account's allowance is used up. A reply also names its chat
    // (X-JusPrin-Chat), so the gateway can keep the chat whole.
    bool           account_sign_in{false};
    // The provider's own web search, as the Responses API tools list names
    // it: OpenAI's spelling, which JusPrin's gateway passes to OpenAI, unless
    // the row gives its own. The Messages API has one spelling, which
    // AnthropicCodec writes.
    std::string    web_search_type{"web_search"};
};

// Every provider this build can talk to, in the order setup lists them.
inline const std::vector<ProviderProfile>& provider_profiles()
{
    static const std::vector<ProviderProfile> rows{
        // JusPrin's own gateway. Its models are aliases ("slicer-1") that the
        // gateway maps to a provider's model, and each alias says which wire
        // format it is served in; account_profile() turns this row into the
        // one a chat talks to. max_tokens serves the Anthropic format.
        // The server the account signs in to is derived from this endpoint.
        // It is JusPrin's host, not Obico's: the server decides by host which
        // brand's accounts a sign-in uses, and JusPrin's are its own.
        // User-Agent names this JusPrin release to the server.
        {"jusprin", ProviderFamily::Responses, "https://jusprinv2.obico.io/ent/jusprin/v2/responses", AuthStyle::Bearer,
         "slicer-1", "JusPrin", {{"User-Agent", Updates::user_agent()}}, 64000, {}, true},
        {"openai", ProviderFamily::Responses, "https://api.openai.com/v1/responses", AuthStyle::Bearer, "gpt-5.4-mini", "OpenAI", {}, 0},
        // OpenRouter serves the Responses API. The default is the model the
        // OpenAI row uses, so the behaviour is the one already evaluated.
        // X-Title names the app in OpenRouter's usage pages. OpenRouter
        // also reads HTTP-Referer, the app's website, to give it a page of
        // its own; this build has no website constant to send, so it sends
        // none. Its web search is a tool of its own, for any model it serves.
        {"openrouter", ProviderFamily::Responses, "https://openrouter.ai/api/v1/responses", AuthStyle::Bearer,
         "openai/gpt-5.4-mini", "OpenRouter", {{"X-Title", "JusPrin"}}, 0, {}, false, "openrouter:web_search"},
        // The Messages API. max_tokens is required there and also bounds the
        // model's thinking, which this model cannot turn off; 64000 is the
        // value Anthropic suggests for streaming requests.
        {"anthropic", ProviderFamily::Anthropic, "https://api.anthropic.com/v1/messages", AuthStyle::ApiKeyHeader,
         "claude-opus-5-5", "Anthropic", {{"anthropic-version", "2023-06-01"}}, 64000},
    };
    return rows;
}

// The row for a provider id, or null when this build has none.
inline const ProviderProfile* profile_for(const std::string& id)
{
    for (const ProviderProfile& profile : provider_profiles())
        if (profile.id == id)
            return &profile;
    return nullptr;
}

inline const ProviderProfile& openai_profile() { return *profile_for("openai"); }

// The provider a JusPrin account signs in to.
inline const ProviderProfile& account_provider()
{
    for (const ProviderProfile& profile : provider_profiles())
        if (profile.account_sign_in)
            return profile;
    throw std::logic_error("provider_profiles() has no account provider");
}

// The wire formats JusPrin's gateway serves a model in, as its model list
// names them, and the endpoint each one is posted to beside the other.
inline constexpr const char* kFormatAnthropic = "anthropic";
inline constexpr const char* kFormatResponses = "responses";

// The wire format a family speaks, named as the gateway names it. A chat's
// record is kept in one.
inline const char* wire_format(ProviderFamily family)
{
    return family == ProviderFamily::Anthropic ? kFormatAnthropic : kFormatResponses;
}

// Whether a fired skill is shown on the request that fired it only. The
// Messages API can clear it from the turns after (a turn-scoped system
// message, behind a beta header); JusPrin's gateway sends only the headers
// it is configured with, so through it skills stay in place, as they do on
// Responses, which has no such message.
inline bool clears_skills(const ProviderProfile& profile)
{
    return profile.family == ProviderFamily::Anthropic && !profile.account_sign_in;
}

// The beta that turn-scoped system messages need.
inline constexpr const char* kClearAtBeta = "mid-conversation-system-clear-at-2026-08-21";

// An account provider's row as one model is served: the family the format
// names, posted to that format's endpoint next to `endpoint` (the last path
// segment is replaced, so an override or a self-hosted server moves both).
// Null for a format this build does not speak.
inline std::optional<ProviderProfile> account_profile(const ProviderProfile& row, const std::string& endpoint,
                                                      const std::string& format)
{
    ProviderProfile profile = row;
    if (format == kFormatAnthropic)
        profile.family = ProviderFamily::Anthropic;
    else if (format == kFormatResponses)
        profile.family = ProviderFamily::Responses;
    else
        return std::nullopt;
    const std::string base  = endpoint.empty() ? row.endpoint : endpoint;
    const std::size_t slash = base.rfind('/');
    profile.endpoint = (slash == std::string::npos ? base : base.substr(0, slash + 1)) +
                       (format == kFormatAnthropic ? "messages" : "responses");
    return profile;
}

} // namespace Slic3r::GUI::JusPrin::Agent
#include "ProviderFactory.hpp"
#include "AnthropicCodec.hpp"
#include "ResponsesCodec.hpp"

#include <boost/log/trivial.hpp>

#include <nlohmann/json.hpp>

#include <algorithm>
#include <atomic>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <utility>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

namespace {

using nlohmann::json;

// A picture or file is sent in one of two shapes: a data URL (Responses) or a
// base64 source with its bytes under "data" (Anthropic).
json without_file_bytes(const json& value)
{
    const auto note = [](const std::string& bytes) { return "[" + std::to_string(bytes.size()) + " characters left out]"; };
    if (value.is_string()) {
        const std::string& text = value.get_ref<const std::string&>();
        return text.rfind("data:", 0) == 0 && text.find(";base64,") != std::string::npos ? json(note(text)) : value;
    }
    if (value.is_array()) {
        json copy = json::array();
        for (const json& child : value)
            copy.push_back(without_file_bytes(child));
        return copy;
    }
    if (!value.is_object())
        return value;
    const bool base64 = value.value("type", json()) == "base64";
    json       copy   = json::object();
    for (auto it = value.begin(); it != value.end(); ++it)
        copy[it.key()] = base64 && it.key() == "data" && it.value().is_string() ? json(note(it.value().get<std::string>())) :
                                                                                  without_file_bytes(it.value());
    return copy;
}

void keep_newest(const std::filesystem::path& directory, std::size_t keep)
{
    std::error_code                    ec;
    std::vector<std::filesystem::path> files;
    for (std::filesystem::directory_iterator it(directory, ec), end; !ec && it != end; it.increment(ec))
        files.push_back(it->path());
    if (files.size() <= keep)
        return;
    // The names start with the time, so name order is age order.
    std::sort(files.begin(), files.end());
    for (std::size_t i = 0; i + keep < files.size(); ++i)
        std::filesystem::remove(files[i], ec);
}

std::unique_ptr<IProviderCodec> codec_for(ProviderFamily family)
{
    switch (family) {
    case ProviderFamily::Responses: return std::make_unique<ResponsesCodec>();
    case ProviderFamily::Anthropic: return std::make_unique<AnthropicCodec>();
    }
    return nullptr;
}

std::string environment(const char* name)
{
    const char* value = std::getenv(name);
    return value == nullptr ? std::string() : std::string(value);
}

} // namespace

std::function<void(const SentRequest&)> request_log_writer(std::filesystem::path directory, std::size_t keep)
{
    return [directory = std::move(directory), keep](const SentRequest& sent) {
        // Two agents can post in the same millisecond: a title beside a reply.
        static std::atomic<unsigned> counter{0};
        const auto now = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch());
        char       name[40];
        std::snprintf(name, sizeof name, "%013lld-%06u.json", static_cast<long long>(now.count()), ++counter % 1000000u);
        std::error_code ec;
        std::filesystem::create_directories(directory, ec);
        std::ofstream file(directory / name, std::ios::binary);
        file << json{{"provider", sent.provider},
                     {"chat", sent.chat_key},
                     {"turn", sent.turn_id},
                     {"sequence", sent.sequence},
                     {"body", without_file_bytes(sent.body)}}
                    .dump();
        file.close();
        if (!file) {
            BOOST_LOG_TRIVIAL(warning) << "Agent request log not written in " << directory.string();
            return;
        }
        keep_newest(directory, keep);
    };
}

AgentServicePtr make_provider_agent(const ProviderProfile&               profile,
                                    const std::string&                   api_key,
                                    const std::string&                   model,
                                    const std::string&                   endpoint,
                                    std::unique_ptr<IAgentHttpTransport> transport,
                                    ProviderListeners                    listeners)
{
    ProviderAgentConfig config;
    config.profile = profile;
    if (!model.empty())
        config.profile.model = model;
    if (!endpoint.empty())
        config.profile.endpoint = endpoint;
    config.api_key          = api_key;
    config.usage_listener   = std::move(listeners.usage);
    config.refusal_listener = std::move(listeners.refusal);
    config.request_listener = std::move(listeners.request);
    return std::make_unique<ProviderAgent>(std::move(config), codec_for(profile.family), std::move(transport));
}

std::string agent_endpoint_override()
{
    if (std::string endpoint = environment("JUSPRIN_AGENT_ENDPOINT"); !endpoint.empty())
        return endpoint;
    return environment("JUSPRIN_OPENAI_ENDPOINT");
}

AgentRuntime resolve_agent_runtime(const AgentSettings&                                         settings,
                                   const std::string&                                           endpoint_override,
                                   const std::function<std::unique_ptr<IAgentHttpTransport>()>& transport,
                                   ProviderListeners                                            listeners)
{
    AgentRuntime runtime;
    runtime.provider = settings.provider.empty() ? "openai" : settings.provider;
    if (!settings.enabled) {
        runtime.unavailable_reason = "The Agent is not enabled.";
        return runtime;
    }
    const ProviderProfile* profile = profile_for(runtime.provider);
    if (profile == nullptr) {
        runtime.unavailable_reason = "The configured Agent provider is not supported.";
        return runtime;
    }
    if (!settings.cloud_consent) {
        runtime.unavailable_reason = "Cloud Agent access requires explicit consent.";
        return runtime;
    }
    if (settings.api_key.empty()) {
        runtime.unavailable_reason = profile->account_sign_in ? "Not signed in to a JusPrin account." :
                                                                "No " + profile->display_name + " API key is configured.";
        return runtime;
    }
    if (profile->account_sign_in) {
        const std::optional<ProviderProfile> served =
            account_profile(*profile, endpoint_override.empty() ? settings.endpoint : endpoint_override, settings.format);
        if (!served) {
            runtime.unavailable_reason = "Sign in to your JusPrin account again.";
            return runtime;
        }
        runtime.service = make_provider_agent(*served, settings.api_key, settings.model, {}, transport(), std::move(listeners));
    } else {
        runtime.service = make_provider_agent(*profile, settings.api_key, settings.model, endpoint_override, transport(),
                                              std::move(listeners));
    }
    runtime.availability = runtime.service->ready() ? AgentAvailability::Ready : AgentAvailability::Unavailable;
    if (runtime.availability == AgentAvailability::Unavailable)
        runtime.unavailable_reason = "The " + profile->display_name + " Agent could not be initialized.";
    return runtime;
}

} // namespace Slic3r::GUI::JusPrin::Agent

